def parse_query_string(query):
    params = {}
    pairs = (pair.split('=', 1) for pair in query[1:].split('&'))

    for key, value in pairs:
        if not key: continue # Skip empty keys due to leading '&'
        val = unquote(value)

        try:
            val = int(val)
        except ValueError:
            pass
        params[key] = val

    return dict(params)

from urllib.parse import unquote

# Example usage:
query_string = 'foo=1&bar=hello'
parsed_dict = parse_query_string(query_string)
print(parsed_dict)  # Output: {'foo': 1, 'bar': 'hello'}
